12	/** Called by a section when it connects, since sections parsed with the tab set upgrade after it. */
13	const sectionsChanged = Symbol("sectionsChanged");
14	
15	/** One section of a tab set. It supplies its tab's label and a value; the tab set shows it. */
16	export class DsTabPanel extends Base {
17	  connectedCallback() {
18	    this.parentElement?.[sectionsChanged]?.();
19	  }
20	  get label() {
21	    return this.getAttribute("label") ?? "";
22	  }
23	  set label(value) {
24	    this.setAttribute("label", value ?? "");
25	  }
26	  /** Defaults to the label. */
27	  get value() {
28	    return this.getAttribute("value") ?? this.label;
29	  }
30	  set value(value) {
31	    if (value == null) this.removeAttribute("value");
32	    else this.setAttribute("value", value);
33	  }
34	}
