36	/** A row of tabs above one panel. Direct section children supply the tabs and their content. */
37	export class DsTabs extends ForwardsFocus(Base) {
38	  static observedAttributes = ["label", "value"];
39	  #tabList;
40	  #panel;
41	  #slot;
42	  #observer;
43	  /** The section last chosen, so a tab whose value repeats an earlier one can still be selected. */
44	  #chosen;
45	
46	  constructor() {
47	    super();
48	    // Manual assignment shows only the selected section; the rest are not rendered.
49	    const root = this.attachShadow({ mode: "open", slotAssignment: "manual" });
50	    root.adoptedStyleSheets = [styleSheet()];
51	    root.innerHTML = `<div class="tab-list" part="tab-list" role="tablist"></div>
52	      <div class="panel" part="panel" role="tabpanel" tabindex="0"><slot></slot></div>`;
53	    this.#tabList = root.querySelector(".tab-list");
54	    this.#panel = root.querySelector(".panel");
55	    this.#slot = root.querySelector("slot");
56	    this.#tabList.addEventListener("click", (event) => {
57	      const tab = event.target.closest('[role="tab"]');
58	      if (tab) this.#select(this.#tabs().indexOf(tab));
59	    });
60	    this.#tabList.addEventListener("keydown", (event) => this.#onKeydown(event));
61	    this.#observer = new MutationObserver((records) => {
62	      // Sections added, removed, or relabeled; changes inside a section's content are not ours.
63	      const ours = (record) =>
64	        record.type === "childList" ? record.target === this : record.target.parentElement === this;
65	      if (records.some(ours)) this.#render();
66	    });
67	  }
68	
69	  connectedCallback() {
70	    this.#observer.observe(this, {
71	      childList: true,
72	      subtree: true,
73	      attributes: true,
74	      attributeFilter: ["label", "value"],
75	    });
76	    this.#render();
77	  }
78	  disconnectedCallback() {
79	    this.#observer.disconnect();
80	  }
81	  attributeChangedCallback() {
82	    if (this.#tabList) this.#sync();
83	  }
84	  [sectionsChanged]() {
85	    this.#render();
86	  }
87	  get [focusTarget]() {
88	    return this.#tabList.querySelector('[aria-selected="true"]');
89	  }
90	  focus(options) {
91	    this[focusTarget]?.focus(options);
92	  }
93	  blur() {
94	    this.shadowRoot.activeElement?.blur();
95	  }
96	  get label() {
97	    return this.getAttribute("label") ?? "";
98	  }
99	  set label(value) {
100	    this.setAttribute("label", value ?? "");
101	  }
102	  /** The selected section's value. An unmatched value selects the first section. */
103	  get value() {
104	    return this.#selected()?.value ?? "";
105	  }
106	  set value(value) {
107	    if (value == null || value === "") this.removeAttribute("value");
108	    else this.setAttribute("value", value);
109	  }
110	
111	  #panels() {
112	    return [...this.children].filter((child) => child instanceof DsTabPanel);
113	  }
114	  #tabs() {
115	    return [...this.#tabList.children];
116	  }
117	  #selected() {
118	    const panels = this.#panels();
119	    const value = this.getAttribute("value");
120	    if (panels.includes(this.#chosen) && this.#chosen.value === value) return this.#chosen;
121	    return panels.find((panel) => panel.value === value) ?? panels[0];
122	  }
123	  #render() {
124	    const focused = this.#tabs().indexOf(this.shadowRoot.activeElement);
125	    this.#tabList.replaceChildren(
126	      ...this.#panels().map((panel, index) => {
127	        const tab = document.createElement("button");
128	        tab.type = "button";
129	        tab.id = `tab-${index}`;
130	        tab.className = "tab";
131	        tab.setAttribute("part", "tab");
132	        tab.setAttribute("role", "tab");
133	        const indicator = document.createElement("span");
134	        indicator.className = "indicator";
135	        indicator.setAttribute("part", "selected-indicator");
136	        indicator.setAttribute("aria-hidden", "true");
137	        tab.append(panel.label, indicator);
138	        return tab;
139	      }),
140	    );
141	    this.#sync();
142	    if (focused !== -1) (this.#tabs()[focused] ?? this[focusTarget])?.focus();
143	  }
144	  #sync() {
145	    const panels = this.#panels();
146	    const selected = this.#selected();
147	    this.#tabList.setAttribute("aria-label", this.label);
148	    for (const [index, tab] of this.#tabs().entries()) {
149	      const isSelected = panels[index] === selected;
150	      tab.setAttribute("aria-selected", String(isSelected));
151	      tab.tabIndex = isSelected ? 0 : -1;
152	      if (isSelected) this.#panel.setAttribute("aria-labelledby", tab.id);
153	    }
154	    this.#panel.hidden = !selected;
155	    this.#slot.assign(...(selected ? [selected] : []));
156	  }
157	  #select(index) {
158	    const panel = this.#panels()[index];
159	    if (!panel) return;
160	    const changed = panel !== this.#selected();
161	    if (changed) {
162	      this.#chosen = panel;
163	      this.setAttribute("value", panel.value);
164	      this.#sync();
165	    }
166	    this.#tabs()[index].focus();
167	    if (changed) this.dispatchEvent(new Event("change", { bubbles: true }));
168	  }
169	  #onKeydown(event) {
170	    const count = this.#tabs().length;
171	    const current = this.#tabs().indexOf(this.shadowRoot.activeElement);
172	    if (current === -1 || count === 0) return;
173	    const forward = getComputedStyle(this).direction === "rtl" ? "ArrowLeft" : "ArrowRight";
174	    const backward = forward === "ArrowRight" ? "ArrowLeft" : "ArrowRight";
175	    const target = {
176	      [forward]: (current + 1) % count,
177	      [backward]: (current - 1 + count) % count,
178	      Home: 0,
179	      End: count - 1,
180	    }[event.key];
181	    if (target === undefined) return;
182	    event.preventDefault();
183	    this.#select(target);
184	  }
185	}
