187	/**
188	 * Registers the tab set under `tagName` and its sections under `panelTagName`. The tab set finds
189	 * its sections by class, so either can be an alias.
190	 */
191	export function defineTabs(tagName = "ds-tabs", panelTagName = "ds-tab-panel") {
192	  definePanel(panelTagName);
193	  defineTabSet(tagName);
194	}
195	const definePanel = defineElement("ds-tab-panel", DsTabPanel);
196	const defineTabSet = defineElement("ds-tabs", DsTabs);
